To implement the ability to plant a seed when the 'p' key is pressed, we need to add a new function called `plantSeed` that will be triggered by the 'p' key press. This function will check if the player is on a tile with a seed, and if so, it will plant a seed on that tile and update the inventory accordingly.

Here's the updated code:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <div id="day"></div>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const gridSize = 32;
        const player = { x: 0, y: 0 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x * gridSize, player.y * gridSize, gridSize, gridSize);
        }

        function drawTile(x, y, crop, stage) {
            ctx.fillStyle = crop === 'seed' ? 'yellow' : 'green';
            ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
            ctx.fillStyle = 'black';
            ctx.font = '12px Arial';
            ctx.fillText(`Stage: ${stage}`, x * gridSize + 10, y * gridSize + 20);
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.fillRect(0, 0, 100, 100);
            ctx.fillStyle = 'black';
            ctx.font = '12px Arial';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 20);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 40);
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawPlayer();
            for (const [key, value] of Object.entries(tiles)) {
                drawTile(key.split(',')[0], key.split(',')[1], value.crop, value.stage);
            }
            drawInventory();
            document.getElementById('day').textContent = `Day: ${day}`;
        }

        function movePlayer(event) {
            const dx = event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowRight' ? 1 : 0;
            const dy = event.key === 'ArrowUp' ? -1 : event.key === 'ArrowDown' ? 1 : 0;
            const newX = player.x + dx;
            const newY = player.y + dy;
            if (newX >= 0 && newX < 20 && newY >= 0 && newY < 15) {
                player.x = newX;
                player.y = newY;
                draw();
            }
        }

        function plantSeed() {
            const tileKey = `${player.x},${player.y}`;
            if (tiles[tileKey] && tiles[tileKey].crop === 'seed') {
                tiles[tileKey] = { crop: 'empty', stage: 0 };
                inventory.seeds--;
                draw();
            }
        }

        function advanceTime() {
            day++;
            draw();
        }

        function harvestCrop() {
            const tileKey = `${player.x},${player.y}`;
            if (tiles[tileKey] && tiles[tileKey].crop === 'seed') {
                tiles[tileKey] = { crop: 'empty', stage: 0 };
                inventory.seeds++;
                inventory.crops--;
                draw();
            }
        }

        function saveGame() {
            localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
        }

        function loadGame() {
            const savedGame = JSON.parse(localStorage.getItem('game'));
            player = savedGame.player;
            tiles = savedGame.tiles;
            inventory = savedGame.inventory;
            day = savedGame.day;
            draw();
        }

        document.addEventListener('keydown', movePlayer);
        document.addEventListener('p', plantSeed);
        document.addEventListener('t', advanceTime);
        document.addEventListener('h', harvestCrop);
        document.addEventListener('s', saveGame);
        document.addEventListener('load', loadGame);

        window.game = { state: () => JSON.parse(JSON.stringify({ player, tiles, inventory, day })) };
    </script>
</body>
</html>
```

### Explanation:
1. **Plant Seed Function (`plantSeed`)**:
   - This function checks if the player is on a tile with a seed (`tiles[tileKey] && tiles[tileKey].crop === 'seed'`).
   - If the condition is true, it updates the tile's crop to 'empty' and decrements the player's seeds by 1.
   - The `draw` function is called to update the display after planting the seed.

2. **Key Event Listeners**:
   - The `keydown` event listener is added to the document to listen for key presses.
   - The 'p' key is used to trigger the `plantSeed` function.
   - The 't' key is used to advance time by incrementing the `day` variable and calling the `draw` function.
   - The 'h' key is used to harvest a crop by checking if the player is on a seed tile and updating the tile's crop to 'empty' and the player's crops by 1.
   - The 's' key is used to save the game state to `localStorage`.
   - The 'load' key is used to load the game state from `localStorage` and update the player, tiles, inventory, and day variables accordingly.

This implementation ensures that the game continues to function as expected while allowing the user to plant seeds, advance time, and harvest crops using the specified keys.
